--[[
	AuctionatorVendor.lua

	Looks up an item's binding type (BoP / BoE / etc.) and required
	disenchanting skill level from a compact, base64-style encoded data
	blob exported from the armory. Two characters of the blob encode one
	item ID: the first for the required DE skill level, the second for
	the binding type.

	NOTE: `gAtr_MI` is machine-generated reference data (2 chars per
	item ID, in ascending order) and is intentionally left untouched.
]]

local addonName, addonTable = ...
local zc = addonTable.zc

-- Item IDs with special-cased binding that the encoded data gets wrong
-- (all are Wrath-era feasts/food that shouldn't be treated as bound).
local BINDING_OVERRIDE_ITEM_IDS = {
	[43015] = true,
	[34753] = true,
	[43480] = true,
	[43478] = true,
}

-- Encoded per-item metadata: 2 characters per item ID (DE-req-level char,
-- binding-type char), ordered by item ID starting at 1.
local gAtr_MI = ""

-----------------------------------------

-- Returns the item's binding type (0 = unbound, 1 = BoP, etc.),
-- optionally against a different encoded data string.
function Atr_GetBonding(itemID, dataBlob)

	if itemID == nil then
		return 0
	end

	if BINDING_OVERRIDE_ITEM_IDS[itemID] then
		return 0
	end

	dataBlob = dataBlob or gAtr_MI

	local charIndex = ((itemID - 1) * 2) + 2

	if charIndex <= string.len(dataBlob) then
		return zc.dec64(string.sub(dataBlob, charIndex, charIndex))
	end

	return 0
end

-- Returns the required disenchanting skill level for an item, optionally
-- against a different encoded data string.
function Atr_DEReqLevel(itemID, dataBlob)

	if itemID == nil then
		return 0
	end

	dataBlob = dataBlob or gAtr_MI

	local charIndex = ((itemID - 1) * 2) + 1

	if charIndex <= string.len(dataBlob) then
		local encodedValue = zc.dec64(string.sub(dataBlob, charIndex, charIndex))
		return (encodedValue == 1) and 1 or (encodedValue * 25)
	end

	return 0
end
